   "mcu_primary": null,
   "mcu_primary_note": "Quad-core ARM Cortex-A7 running up to 1.3 GHz with 32 KB L1 and 512 KB L2 cache, per Hak5's own comparison page. The specific SoC part number has never been published.",
   "mcu_secondary": null,
   "radios": [
    {
     "ic": null,
     "role": "bluetooth",
     "note": "Bluetooth Low Energy, added in the Mark II. Used for wireless geofencing and remote triggers via the WAIT_FOR_PRESENT and WAIT_FOR_NOT_PRESENT extensions, which read the surrounding BLE landscape to /tmp/bt_observation. Chipset not published."
    }
   ],
   "display": null,
   "battery_mah": null,
