   "mcu_secondary": null,
   "radios": [
    {
     "ic": null,
     "role": "nfc",
     "note": "13.56 MHz only, same software-codec approach as the RevG. No 125 kHz hardware."
    }
   ],
   "display": null,
   "battery_mah": null,
   "battery_note": "Integrated Li-Po; capacity not published. The RRG fork's changelog highlights improved power management and battery indication over the official RevG firmware.",
   "charging": "USB-C",
   "pmic": null,
   "storage": "8 card configuration slots",
