    {
     "ic": "ESP32 (integrated)",
     "role": "wifi",
     "note": "2.4 GHz on most boards; 2.4 and 5 GHz only on the ESP32-C5 versions"
    },
    {
     "ic": "ESP32 (integrated)",
     "role": "ble",
     "note": "BLE scanning and spam via Marauder"
    }
