  "firmware_kind": "stock",
  "firmware_repo": "https://github.com/greatscottgadgets/hackrf",
  "firmware_note": "Stock firmware turns the board into a dumb USB radio front end; all signal processing happens on the host PC in GNU Radio, SDR++, SDRangel, etc.",
  "vendor": "Great Scott Gadgets",
  "vendor_url": "https://greatscottgadgets.com",
  "product_url": "https://greatscottgadgets.com/hackrf/one/",
